add_filter( 'woocommerce_sale_flash', 'perfectpixel_sale_countdown_badge', 20, 3 );

function perfectpixel_sale_countdown_badge( $html, $post, $product ) {
	if ( ! is_product() || ! $product || get_queried_object_id() !== $product->get_id() ) {
		return $html;
	}
	$end = $product->get_date_on_sale_to();
	if ( ! $end || $end->getTimestamp() <= time() ) {
		return $html;
	}
	ob_start();
	?>
	<span class="onsale perfectpixel-sale-countdown" data-end="<?php echo esc_attr( $end->getTimestamp() ); ?>" style="min-width:auto;padding:.25em .75em;white-space:nowrap"><?php echo esc_html( '{{countdown_prefix}}' ); ?> <span class="perfectpixel-countdown-time"></span></span>
	<script>
	( function ( badge ) {
		var end  = parseInt( badge.getAttribute( 'data-end' ), 10 ) * 1000;
		var out  = badge.querySelector( '.perfectpixel-countdown-time' );
		var days = <?php echo wp_json_encode( '{{countdown_days}}' ); ?>;
		var pad  = function ( n ) { return ( n < 10 ? '0' : '' ) + n; };
		var tick = function () {
			var left = Math.max( 0, Math.floor( ( end - Date.now() ) / 1000 ) );
			var d = Math.floor( left / 86400 ), h = Math.floor( left % 86400 / 3600 ), m = Math.floor( left % 3600 / 60 ), s = left % 60;
			out.textContent = ( d ? d + ' ' + days + ' ' : '' ) + pad( h ) + ':' + pad( m ) + ':' + pad( s );
			if ( left > 0 ) {
				setTimeout( tick, 1000 );
			}
		};
		tick();
	} )( document.currentScript.previousElementSibling );
	</script>
	<?php
	return ob_get_clean();
}
